/// <summary>
/// This is a service class for the Process invoice matching claims batch job.
/// </summary>
class METAutoInvoiceMatchingClaimsProcessService
{
}

Method.Source:
/// <summary>
/// Claim generation process.
/// </summary>
public void processOperation()
{
    VendInvoiceInfoTable claimInvoiceTable;        
    VendInvoiceInfoLine claimInvoiceLine;

    if (METVendParameters::find().EnableMetcashMatchingLogic)
    {
        // Incident 424978: WILO - EDI Invoices with "Metcash Invoice Matching Status" is failed should not be submitted to workflow
        // Split claim invoice first then EDI invoice            
        while select claimInvoiceTable
            where claimInvoiceTable.METClaimInvoice == NoYes::Yes
            || claimInvoiceTable.METABBYYInvoice == NoYes::Yes
        {
            if (!claimInvoiceTable.skipCustomInvoiceMatching() && !claimInvoiceTable.isLandedCostEnabled())
            {
                try
                {
                    this.submitClaimInvoiceToWorkflow(claimInvoiceTable);
                }
                catch
                {
                    continue;
                }
            }
        }

        // EDI invoice added PVI line quantity reason and price reason blank to submit to workflow
        while select claimInvoiceTable
               where claimInvoiceTable.METEDIInvoice == NoYes::Yes
                  && claimInvoiceTable.METEDIGrnStatusValue == METEDIGrnStatus::GRN                     
                  && claimInvoiceTable.RequestStatus == VendInvoiceRequestStatus::Draft // only draft gets submitted to workflow doing it here upfront before waiting for canSubmitToWorkflow
            notexists join claimInvoiceLine
                     where claimInvoiceLine.ParmId == claimInvoiceTable.ParmId
                        && claimInvoiceLine.TableRefId == claimInvoiceTable.TableRefId
                        && (claimInvoiceLine.ReasonTableRef != 0
                        ||  claimInvoiceLine.MetPriceVarianceReasonCode != 0)
        {
            if (!claimInvoiceTable.skipCustomInvoiceMatching() 
            &&  !claimInvoiceTable.isLandedCostEnabled()
            &&   claimInvoiceTable.displayMetMatchStatus() == METMatchStatus::Pass)
            {
                try
                {
                    this.submitClaimInvoiceToWorkflow(claimInvoiceTable);
                }
                catch
                {
                    continue;
                }
            }
        }
    }
}

/// <summary>
/// Submit claim to workflow.
/// </summary>
/// <param name = "_claimInvoiceTable">VendInvoiceInfoTable</param>
private void submitClaimInvoiceToWorkflow(VendInvoiceInfoTable _claimInvoiceTable)
{
    //Do not submit the Claim invoice until the original invoice is posted
    if (_claimInvoiceTable.METClaimInvoice && _claimInvoiceTable.METClaimForInvoice != '')
    {
        VendInvoiceJour invJour;
        select firstonly RecId from invJour
            where invJour.InvoiceId == _claimInvoiceTable.METClaimForInvoice
            && invJour.PurchId == _claimInvoiceTable.PurchId
            && invJour.InvoiceAccount == _claimInvoiceTable.InvoiceAccount;

        if (!invJour)
        {
            return;
        }
    }

    if(_claimInvoiceTable && _claimInvoiceTable.existLine() && _claimInvoiceTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(_claimInvoiceTable, _claimInvoiceTable.Description);
    }
}
